// Word's line height and ascent for a font, from its own numbers (metrics.js, generated by tools/fontmetrics.mjs).
// Word's single line is the larger of the font's hhea total (ascender + descender + line gap) and its Windows ascent +
// descent, or its typo total where the font asks for its typo metrics; in a line of runs in several sizes or fonts,
// its ascent is the Windows ascent plus whatever the hhea total is larger by (GDI's external leading). Checked against
// Word's prints of generated documents (2026-11-24, 33 fonts at 10, 11, 12 and 14pt: every line within 0.001em of
// the rule, Book Antiqua's 1.2427 among them, where its hhea total is 1.2056; MS Gothic's by eastMetrics below).
import { FONT_UNITS, RECORDED, ALIASES, MEASURED, EAST } from './metrics.js';

const r4 = (v) => Math.round(v * 10000) / 10000;
const cache = new Map();

/**
 * Word's numbers per em for a font (lowercase family name), or null where none are known:
 * line (single line height), ascent (hhea ascender + line gap: where the browser puts the baseline, which the print
 * offsets were fitted on, baseline.js), wordAscent (Word's ascent in a line of mixed runs), winDescent (the Windows
 * descent where it's larger than hhea's, which Word takes under a picture, picfix.js; else null).
 */
export function fontMetrics(family) {
  const key = Object.hasOwn(ALIASES, family) ? ALIASES[family] : family;
  if (cache.has(key)) return cache.get(key);
  let m = null;
  if (Object.hasOwn(FONT_UNITS, key)) {
    const [upm, a, d, g, wa, wd, ta, td, tg] = FONT_UNITS[key];
    const hhea = a + d + g, win = wa + wd;
    m = ta == null
      ? { line: r4(Math.max(hhea, win) / upm), ascent: r4((a + g) / upm), wordAscent: r4((wa + Math.max(0, hhea - win)) / upm), winDescent: wd > d ? r4(wd / upm) : null }
      : { line: r4((ta + td + tg) / upm), ascent: r4((a + g) / upm), wordAscent: r4((ta + tg) / upm), winDescent: null };
  } else if (Object.hasOwn(RECORDED, key)) {
    const { line, ascent } = RECORDED[key];
    m = { line, ascent, wordAscent: ascent, winDescent: null };
  }
  // (An East Asian font's line is its own rule's: MS Gothic's 332/256, Word's 1.2967-1.2973em at 10 to 14pt.)
  if (m && EAST.includes(family)) m = { ...m, line: r4(eastMetrics(family)[1]) };
  if (m && Object.hasOwn(MEASURED, key)) m = { ...m, ...MEASURED[key] };
  cache.set(key, m);
  return m;
}

/**
 * An East Asian font's [ascent, line] per em in Word, or null for another font: its Windows ascent and descent each
 * 1.3 times and cut to a whole unit, the added part half above and half below (MS Gothic: 220 and 36 of 256 give
 * 258 and 332; Word's prints of 70 generated documents, and 1.2967-1.2973em lines at 10 to 14pt, 2026-11-24).
 */
export function eastMetrics(family) {
  if (!EAST.includes(family)) return null;
  const key = Object.hasOwn(ALIASES, family) ? ALIASES[family] : family;
  const [upm, , , , wa, wd] = FONT_UNITS[key];
  const up = Math.floor(wa * 1.3), down = Math.floor(wd * 1.3);
  const added = up - wa + down - wd;
  return [(wa + added / 2) / upm, (up + down) / upm];
}
